/**
 * utils/dom.js
 * Centralized DOM querying and manipulation helpers.
 */

export const qs = (selector, parent = document) =>
  parent.querySelector(selector);
export const qsa = (selector, parent = document) =>
  parent.querySelectorAll(selector);

